/**
 * The translation of the SQL generated by @abaplint/transpiler to PostgreSQL, and the savepoints
 * that keep a LUW's transaction usable after a failing statement (decision D26).
 */

import { PGlite } from "@electric-sql/pglite";
import { PGliteDialect, sql } from "kysely";
import { describe, expect, it } from "vitest";
import { AbapSqlError, translateSelect } from "../src/abap/sql.js";
import { createDatabase, PGLITE_PARSERS, withSavepoint } from "../src/db/database.js";

const T = `"rapt_abap"."zrt_travel"`;

describe("ABAP SQL translation", () => {
  it("turns UP TO n ROWS into a LIMIT at the end, none for 0", () => {
    expect(translateSelect(`SELECT * FROM ${T} WHERE "travel_id" = '1' UP TO 1 ROWS`)).toBe(`SELECT * FROM ${T} WHERE "travel_id" = '1' LIMIT 1`);
    expect(translateSelect(`SELECT * FROM ${T} UP TO 3 ROWS ORDER BY "begin_date" ASCENDING , "travel_id" DESCENDING`)).toBe(`SELECT * FROM ${T} ORDER BY "begin_date" ASC , "travel_id" DESC LIMIT 3`);
    expect(translateSelect(`SELECT * FROM ${T} UP TO 0 ROWS`)).toBe(`SELECT * FROM ${T}`);
  });

  it("orders by the primary key", () => {
    expect(translateSelect(`SELECT * FROM ${T} ORDER BY PRIMARY KEY`, ["travel_uuid"])).toBe(`SELECT * FROM ${T} ORDER BY "travel_uuid"`);
    expect(translateSelect(`SELECT * FROM ${T} ORDER BY PRIMARY KEY`)).toBe(`SELECT * FROM ${T}`);
    expect(translateSelect(`SELECT * FROM ${T} ORDER BY ORDER BY "travel_id" `)).toBe(`SELECT * FROM ${T} ORDER BY "travel_id"`);
  });

  it("translates the comparison keywords, alias fields and the case of identifiers, not the literals", () => {
    expect(translateSelect(`SELECT "t"."TravelID" FROM "rapt_abap"."zrt_r_travel" AS t INNER JOIN ${T} AS b ON "t"."TravelUUID" = b~travel_uuid WHERE "BookingFee" GE 10 AND "Description" NE 'It''s "TravelID" GE'`)).toBe(
      `SELECT "t"."travelid" FROM "rapt_abap"."zrt_r_travel" AS t INNER JOIN ${T} AS b ON "t"."traveluuid" = b.travel_uuid WHERE "bookingfee" >= 10 AND "description" <> 'It''s "TravelID" GE'`,
    );
    expect(translateSelect(`SELECT COUNT(*) FROM ${T} WHERE "booking_fee" > 10.5`)).toBe(`SELECT COUNT(*) FROM ${T} WHERE "booking_fee" > 10.5`);
  });

  it("reads only the tables and CDS entities of the application", () => {
    // the MESSAGE statement of the runtime looks for T100 first: it falls back to the message classes
    expect(() => translateSelect("SELECT * FROM t100 WHERE sprsl='E' AND arbgb='ZRT_TRAVEL' AND msgnr='001' LIMIT 1")).toThrow(AbapSqlError);
    expect(() => translateSelect(`SELECT * FROM ${T} WHERE EXISTS (SELECT 1 FROM "zrt_booking")`)).toThrow("not a table or a CDS entity");
    expect(() => translateSelect(`SELECT * FROM ${T} WHERE "description" = 'open`)).toThrow("unterminated literal");
  });
});

describe("savepoints", () => {
  it("keep the transaction usable after a failing statement", async () => {
    const pglite = await PGlite.create({ parsers: PGLITE_PARSERS });
    const db = createDatabase(new PGliteDialect({ pglite }));
    try {
      await sql.raw("CREATE TABLE t (id integer PRIMARY KEY)").execute(db);
      await db.transaction().execute(async (trx) => {
        await sql.raw("INSERT INTO t VALUES (1)").execute(trx);
        await expect(withSavepoint(trx, () => sql.raw("INSERT INTO t VALUES (1)").execute(trx))).rejects.toThrow(/duplicate key/);
        const ok = await withSavepoint(trx, () => sql.raw<{ n: number }>("SELECT count(*)::int AS n FROM t").execute(trx));
        expect(ok.rows[0]?.n).toBe(1);
        await sql.raw("INSERT INTO t VALUES (2)").execute(trx);
      });
      const rows = await sql.raw<{ id: number }>("SELECT id FROM t ORDER BY id").execute(db);
      expect(rows.rows.map((r) => r.id)).toEqual([1, 2]);
    } finally {
      await db.destroy();
    }
  });
});
